import {ready,truckOptions} from './engine.mjs';import {normalizeAIRequest} from './ai-context.mjs';
export function browserAIRequest(state,{feature,shipmentId,orderIds=[],truckId,departure,documentText=''}={}){
 let source,lines,truck,extra=0;
 if(orderIds.length){const orders=orderIds.map(id=>state.orders.find(o=>o.id===id));if(orders.some(o=>!o))throw Error('Select valid source orders.');source=orders[0];lines=orders.map(o=>{const m=state.skus.find(m=>m.id===o.sku);return {order:o.id,sku:o.sku,quantity:ready(state,o),unitWeight:m.unitWeight,unitVolume:m.unitVolume,unitValue:m.unitValue};});truck=truckOptions(state,lines.map(l=>({sku:l.sku,planned:l.quantity})),{route:source.route,principal:source.principal}).find(t=>t.id===truckId);source={...source,id:orderIds.join(' + '),departure};}
 else{source=state.shipments.find(s=>s.id===shipmentId);if(!source)throw Error('Choose a shipment.');lines=source.lines.map(l=>{const m=state.skus.find(m=>m.id===l.sku);return {order:l.order,sku:l.sku,quantity:l.packed,unitWeight:m.unitWeight,unitVolume:m.unitVolume,unitValue:m.unitValue};});const t=source.truckSnapshot||state.trucks.find(t=>t.id===source.truck);truck={...t,rate:source.estimate};}
 if(!truck)throw Error('Select a truck first.');const selected=new Set(lines.map(l=>l.order));if(lines.every(l=>l.sku===lines[0].sku))extra=state.orders.filter(o=>!selected.has(o.id)&&o.sku===lines[0].sku&&o.principal===source.principal&&o.warehouse===source.warehouse&&o.destination===source.destination&&o.platform===source.platform).reduce((n,o)=>n+ready(state,o),0);
 return normalizeAIRequest({feature,snapshot:{id:source.id,principal:state.principals.find(p=>p.id===source.principal)?.name,origin:state.warehouses.find(w=>w.id===source.warehouse)?.name,destination:source.destination,route:source.route,departure:source.departure,lines,truck:{name:truck.name,capacity:truck.capacity,volume:truck.volume,freight:truck.rate},additionalCompatibleUnits:extra,documents:feature==='documents'?['invoice','eway','lr'].map(kind=>{const d=source.documents?.find(d=>d.kind===kind);return {kind,hasFile:!!d?.data?.startsWith('data:'),verified:d?.verified===true,quantityMatches:d?.quantity===lines.reduce((n,l)=>n+l.quantity,0)};}):[]},documentText});
}
